package br.ucb.claquete.controller;
import br.ucb.claquete.service.AcervoJdbcService;import java.net.URI;import java.time.LocalDate;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/disponibilidade")public class DisponibilidadeController{private final AcervoJdbcService s;public DisponibilidadeController(AcervoJdbcService s){this.s=s;}@GetMapping public List<Map<String,Object>>listar(@RequestParam(required=false)String plataforma,@RequestParam(required=false)String genero,@RequestParam(required=false)LocalDate vigenteEm){return s.disponibilidades(plataforma,genero,vigenteEm);}@GetMapping("/{filmeId}/{plataformaId}/{dataInicio}")public Map<String,Object>buscar(@PathVariable int filmeId,@PathVariable int plataformaId,@PathVariable LocalDate dataInicio){return s.disponibilidade(filmeId,plataformaId,dataInicio);}@PostMapping public ResponseEntity<Map<String,Object>>criar(@RequestBody Map<String,Object>r){Map<String,Object>x=s.criarDisponibilidade(r);return ResponseEntity.created(URI.create("/api/disponibilidade/"+x.get("filmeId")+"/"+x.get("plataformaId")+"/"+x.get("dataInicio"))).body(x);}@PutMapping("/{filmeId}/{plataformaId}/{dataInicio}")public Map<String,Object>atualizar(@PathVariable int filmeId,@PathVariable int plataformaId,@PathVariable LocalDate dataInicio,@RequestBody Map<String,Object>r){return s.atualizarDisponibilidade(filmeId,plataformaId,dataInicio,r);}@DeleteMapping("/{filmeId}/{plataformaId}/{dataInicio}")@ResponseStatus(HttpStatus.NO_CONTENT)public void excluir(@PathVariable int filmeId,@PathVariable int plataformaId,@PathVariable LocalDate dataInicio){s.excluirDisponibilidade(filmeId,plataformaId,dataInicio);}}
